def minDaysDisconnect(grid: list[list[int]]) -> int:
    R, C = len(grid), len(grid[0])
    def count_islands():
        visited = set()
        islands = 0
        def dfs(r, c):
            visited.add((r, c))
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == 1 and (nr, nc) not in visited:
                    dfs(nr, nc)
        for r in range(R):
            for c in range(C):
                if grid[r][c] == 1 and (r, c) not in visited:
                    islands += 1
                    dfs(r, c)
        return islands
    if count_islands() != 1: return 0
    # Try removing 1 cell
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 1:
                grid[r][c] = 0
                if count_islands() != 1:
                    grid[r][c] = 1
                    return 1
                grid[r][c] = 1
    return 2

